import React, { Suspense } from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import ThemeProvider from './contexts/ThemeProvider';
import { AuthProvider } from './contexts/AuthContext';
import ProtectedRoute from './components/ProtectedRoute';
import Layout from './components/Layout';
import MainPage from './pages/MainPage';
import LoginPage from './pages/LoginPage';
import RegisterPage from './pages/RegisterPage';
import MyBookingsPage from './pages/MyBookingsPage';
import BookingSuccessPage from './pages/BookingSuccessPage';
import FindBookingPage from './pages/FindBookingPage';
import AdminLoginPage from './pages/AdminLoginPage';
import AdminDashboard from './pages/AdminDashboard';
import SettingsPage from './pages/SettingsPage';
import { Typography, Box, CircularProgress } from '@mui/material';
import PageTransition from './components/PageTransition';
import './ModernApp.css';

function Loader() {
  return (
    <Box minHeight="40vh" display="grid" sx= {{ placeItems: "center" }}>
      <CircularProgress />
    </Box>
  );
}

export default function App() {
  return (
    <BrowserRouter>
      <ThemeProvider>
        <AuthProvider>
          <Suspense fallback={<Loader />}>
            <Routes>
              <Route element={<Layout />}>
                <Route index element={<MainPage />} />
                <Route path="login" element={<LoginPage />} />
                <Route path="register" element={<RegisterPage />} />
                <Route path="find-booking" element={<FindBookingPage />} />
                <Route path="booking-success" element={<BookingSuccessPage />} />
                <Route path="admin">
                  <Route path="login" element={<AdminLoginPage />} />
                  <Route element={<ProtectedRoute />}>
                    <Route path="dashboard" element={<AdminDashboard />} />
                  </Route>
                </Route>
                <Route element={<ProtectedRoute />}>
                  <Route path="my-bookings" element={<MyBookingsPage />} />
                  <Route path="settings" element={<SettingsPage />} />
                </Route>
                <Route
                  path="*"
                  element={
                    <Box textAlign="center" py={8}>
                      <Typography variant="h4" fontWeight={800}>
                        Page not found
                      </Typography>
                      <Typography color="text.secondary">
                        The page you’re looking for doesn’t exist.
                      </Typography>
                    </Box>
                  }
                />
              </Route>
            </Routes>
          </Suspense>
        </AuthProvider>
      </ThemeProvider>
    </BrowserRouter>
  );
}

import React from 'react';
import { Box, Container, Typography, Button, Stack } from '@mui/material';
import BentoGrid from '../components/BentoGrid';
import BentoItem from '../components/BentoItem';
import {
  AirportShuttle as ShuttleIcon,
  Map as MapIcon,
  Schedule as ScheduleIcon,
  Payment as PaymentIcon,
  LocalOffer as OffersIcon,
  TrendingUp as TrendingIcon,
} from '@mui/icons-material';

// Hero section with bento layout
export const HeroSection = () => {
  return (
    <Box sx={{ py: 6, mb: 4 }}>
      <Container>
        <Typography
          variant="h2"
          sx={{
            mb: 2,
            fontWeight: 900,
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
            WebkitBackgroundClip: 'text',
            WebkitTextFillColor: 'transparent',
          }}
        >
          Your Journey Starts Here
        </Typography>
        <Typography variant="h6" sx={{ mb: 4, opacity: 0.7 }}>
          Book your shuttle ride in just a few clicks
        </Typography>
      </Container>
    </Box>
  );
};

// Features section with bento grid
export const FeaturesSection = () => {
  const features = [
    {
      title: 'Real-time Tracking',
      description: 'Track your shuttle in real-time with live GPS updates',
      icon: <MapIcon />,
      span: 1,
    },
    {
      title: 'Easy Booking',
      description: 'Book your seats with our simple and intuitive interface',
      icon: <ShuttleIcon />,
      span: 1,
    },
    {
      title: 'Scheduled Rides',
      description: 'Check available schedules and pick your preferred time',
      icon: <ScheduleIcon />,
      span: 1,
    },
    {
      title: 'Secure Payments',
      description: 'Multiple payment options with secure transactions',
      icon: <PaymentIcon />,
      span: 2,
    },
    {
      title: 'Special Offers',
      description: 'Get exclusive deals and discounts on every booking',
      icon: <OffersIcon />,
      span: 1,
    },
  ];

  return (
    <Box sx={{ py: 6 }}>
      <Container>
        <Typography variant="h4" sx={{ mb: 4, fontWeight: 800 }}>
          Why Choose ShuttleNow?
        </Typography>
        <BentoGrid columns={{ xs: 1, sm: 2, md: 3 }} gap={3}>
          {features.map((feature, idx) => (
            <BentoItem
              key={idx}
              title={feature.title}
              description={feature.description}
              icon={feature.icon}
              span={feature.span}
            >
              <Button variant="outlined" size="small" sx={{ mt: 'auto' }}>
                Learn More
              </Button>
            </BentoItem>
          ))}
        </BentoGrid>
      </Container>
    </Box>
  );
};

// Stats section with bento layout
export const StatsSection = () => {
  const stats = [
    { label: 'Active Users', value: '50K+' },
    { label: 'Rides Completed', value: '100K+' },
    { label: 'Cities Covered', value: '25+' },
    { label: 'Avg Rating', value: '4.8⭐' },
  ];

  return (
    <Box sx={{ py: 6, mb: 4 }}>
      <Container>
        <Typography variant="h4" sx={{ mb: 4, fontWeight: 800 }}>
          By The Numbers
        </Typography>
        <BentoGrid columns={{ xs: 2, sm: 2, md: 4 }} gap={2}>
          {stats.map((stat, idx) => (
            <BentoItem key={idx} span={1}>
              <Stack sx={{ textAlign: 'center' }}>
                <Typography variant="h5" sx={{ fontWeight: 800, color: 'primary.main' }}>
                  {stat.value}
                </Typography>
                <Typography variant="body2" sx={{ opacity: 0.7, mt: 1 }}>
                  {stat.label}
                </Typography>
              </Stack>
            </BentoItem>
          ))}
        </BentoGrid>
      </Container>
    </Box>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../utils/api';
import EventForm from './EventForm';
import { socket } from '../utils/socket';
import { Event } from '../types/types';
import {
  Box,
  Typography,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Stack,
  IconButton,
  Grid,
} from '@mui/material';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import DirectionsBusIcon from '@mui/icons-material/DirectionsBus';
import QrCodeScannerIcon from '@mui/icons-material/QrCodeScanner';
import GlassCard from '../components/GlassCard';
import { useColorMode } from '../contexts/ThemeProvider';
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer
} from 'recharts';

interface AdminMetrics {
  totalBookings: number;
  totalRevenue: number;
  totalSeatsAvailable: number;
  totalSeatsBooked: number;
  fillRate: number;
  revenueByEvent: { eventName: string; revenue: number; bookings: number }[];
}

const AdminDashboard = () => {
  const [events, setEvents] = useState<Event[]>([]);
  const [isModalOpen, setIsModalOpen] = useState<boolean>(false);
  const [editingEvent, setEditingEvent] = useState<Event | null>(null);
  const navigate = useNavigate();
  const { mode } = useColorMode();
  const simulationIntervalRef = useRef<NodeJS.Timeout | null>(null);
  const [metrics, setMetrics] = useState<AdminMetrics | null>(null);

  const fetchEvents = async () => {
    try {
      const res = await api.get<Event[]>('/events');
      setEvents(res.data);
    } catch (error) {
      console.error('Failed to fetch events:', error);
    }
  };

  const fetchMetrics = async () => {
    try {
      const res = await api.get<AdminMetrics>('/admin/metrics');
      setMetrics(res.data);
    } catch (error) {
      console.error('Failed to fetch metrics:', error);
    }
  };

  useEffect(() => {
    if (!localStorage.getItem('adminToken')) navigate('/admin/login');
    else {
      fetchEvents();
      fetchMetrics();
    }

    // Cleanup simulation on component unmount
    return () => {
      if (simulationIntervalRef.current) {
        clearInterval(simulationIntervalRef.current);
      }
    };
  }, [navigate]);

  const handleLogout = () => {
    localStorage.removeItem('adminToken');
    navigate('/admin/login');
  };

  const handleCreate = () => {
    setEditingEvent(null);
    setIsModalOpen(true);
  };

  const handleEdit = (event: Event) => {
    setEditingEvent(event);
    setIsModalOpen(true);
  };

  const handleDelete = async (eventId: string) => {
    if (window.confirm('Are you sure?')) {
      try {
        await api.delete(`/admin/events/${eventId}`);
        fetchEvents();
      } catch (error) {
        alert('Could not delete event.');
      }
    }
  };

  const handleSave = () => {
    setIsModalOpen(false);
    fetchEvents();
  };

  const handleSimulateDrive = (event: Event) => {
    // Clear any existing simulation
    if (simulationIntervalRef.current) {
      clearInterval(simulationIntervalRef.current);
    }

    if (!event.lat || !event.lng || !event.destLat || !event.destLng) {
      alert('Event is missing origin or destination coordinates. Cannot simulate drive.');
      return;
    }

    alert(`Simulating drive for ${event.name}. Check the main page map!`);

    const startLat = event.lat;
    const startLng = event.lng;
    const endLat = event.destLat;
    const endLng = event.destLng;

    const totalSteps = 100; // e.g., 100 updates
    let currentStep = 0;

    simulationIntervalRef.current = setInterval(() => {
      if (currentStep >= totalSteps) {
        if (simulationIntervalRef.current) clearInterval(simulationIntervalRef.current);
        return;
      }

      // Linear interpolation for a smooth line
      const progress = currentStep / totalSteps;
      const currentLat = startLat + (endLat - startLat) * progress;
      const currentLng = startLng + (endLng - startLng) * progress;

      socket.emit('update-shuttle-location', {
        eventId: event._id,
        lat: currentLat,
        lng: currentLng,
      });

      currentStep++;
    }, 1000); // update every second
  };

  return (
    <Box sx={{ p: { xs: 2, md: 4 }, minHeight: 'calc(100vh - 96px)' }}>
      <GlassCard sx={{ p: { xs: 3, md: 5 } }}>
        <Stack direction={{ xs: 'column', sm: 'row' }} justifyContent="space-between" alignItems={{ xs: 'flex-start', sm: 'center' }} spacing={3} sx={{ mb: 4 }}>
          <Typography variant="h3" component="h1" fontWeight={900} sx={{
            background: mode === 'light' ? 'linear-gradient(45deg, #2563eb, #3b82f6)' : 'linear-gradient(45deg, #2dd4bf, #0ea5e9)',
            WebkitBackgroundClip: 'text',
            WebkitTextFillColor: 'transparent',
            letterSpacing: -1
          }}>
            Admin Dashboard
          </Typography>
          <Button
            onClick={handleLogout}
            variant="outlined"
            color="error"
            sx={{ borderRadius: 3, fontWeight: 700 }}
          >
            Logout
          </Button>
        </Stack>

        {metrics && (
          <Box sx={{ mb: 6 }}>
            <Grid container spacing={3} sx={{ mb: 4 }}>
              <Grid size={{ xs: 12, md: 4 }}>
                <GlassCard sx={{ p: 3, textAlign: 'center', bgcolor: mode === 'light' ? 'rgba(59, 130, 246, 0.05)' : 'rgba(45, 212, 191, 0.1)' }}>
                  <Typography variant="h6" color="text.secondary" fontWeight={700}>Total Revenue</Typography>
                  <Typography variant="h3" fontWeight={900} sx={{ color: mode === 'light' ? 'primary.main' : '#2dd4bf' }}>
                    ${metrics.totalRevenue.toLocaleString()}
                  </Typography>
                </GlassCard>
              </Grid>
              <Grid size={{ xs: 12, md: 4 }}>
                <GlassCard sx={{ p: 3, textAlign: 'center', bgcolor: mode === 'light' ? 'rgba(59, 130, 246, 0.05)' : 'rgba(45, 212, 191, 0.1)' }}>
                  <Typography variant="h6" color="text.secondary" fontWeight={700}>Total Bookings</Typography>
                  <Typography variant="h3" fontWeight={900} sx={{ color: mode === 'light' ? 'primary.main' : '#2dd4bf' }}>
                    {metrics.totalBookings.toLocaleString()}
                  </Typography>
                </GlassCard>
              </Grid>
              <Grid size={{ xs: 12, md: 4 }}>
                <GlassCard sx={{ p: 3, textAlign: 'center', bgcolor: mode === 'light' ? 'rgba(59, 130, 246, 0.05)' : 'rgba(45, 212, 191, 0.1)' }}>
                  <Typography variant="h6" color="text.secondary" fontWeight={700}>System Fill Rate</Typography>
                  <Typography variant="h3" fontWeight={900} sx={{ color: mode === 'light' ? 'primary.main' : '#2dd4bf' }}>
                    {metrics.fillRate}%
                  </Typography>
                </GlassCard>
              </Grid>
            </Grid>

            <Typography variant="h6" fontWeight={800} sx={{ mb: 2, ml: 1 }}>Revenue by Route</Typography>
            <GlassCard sx={{ p: 3, height: 350 }}>
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={metrics.revenueByEvent} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                  <defs>
                    <linearGradient id="colorRevenue" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor={mode === 'light' ? '#3b82f6' : '#2dd4bf'} stopOpacity={0.8} />
                      <stop offset="95%" stopColor={mode === 'light' ? '#3b82f6' : '#2dd4bf'} stopOpacity={0} />
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" stroke={mode === 'light' ? 'rgba(0,0,0,0.1)' : 'rgba(255,255,255,0.1)'} vertical={false} />
                  <XAxis dataKey="eventName" stroke={mode === 'light' ? '#64748b' : '#94a3b8'} />
                  <YAxis stroke={mode === 'light' ? '#64748b' : '#94a3b8'} tickFormatter={(value) => `$${value}`} />
                  <Tooltip
                    contentStyle={{
                      backgroundColor: mode === 'light' ? 'rgba(255,255,255,0.9)' : 'rgba(15,23,42,0.9)',
                      borderRadius: '12px',
                      border: 'none',
                      boxShadow: '0 4px 20px rgba(0,0,0,0.1)'
                    }}
                    itemStyle={{ color: mode === 'light' ? '#0f172a' : '#f8fafc', fontWeight: 800 }}
                    formatter={(value: any) => [`$${value}`, 'Revenue']}
                  />
                  <Area type="monotone" dataKey="revenue" stroke={mode === 'light' ? '#3b82f6' : '#2dd4bf'} strokeWidth={3} fillOpacity={1} fill="url(#colorRevenue)" />
                </AreaChart>
              </ResponsiveContainer>
            </GlassCard>
          </Box>
        )}

        <Stack direction={{ xs: 'column', sm: 'row' }} justifyContent="space-between" alignItems="center" sx={{ mb: 3 }}>
          <Typography variant="h5" component="h2" fontWeight={800} color="text.secondary">
            Manage Routes & Events
          </Typography>
          <Stack direction="row" spacing={2} sx={{ mt: { xs: 2, sm: 0 } }}>
            <Button
              variant="outlined"
              startIcon={<QrCodeScannerIcon />}
              disabled
              sx={{
                borderRadius: 3,
                fontWeight: 800,
                bgcolor: mode === 'light' ? 'rgba(0,0,0,0.02)' : 'rgba(255,255,255,0.02)'
              }}
            >
              Scan QR (Coming Soon)
            </Button>
            <Button
              variant="contained"
              onClick={handleCreate}
              sx={{
                borderRadius: 3,
                fontWeight: 800,
                backgroundImage: mode === 'light' ? 'linear-gradient(135deg, #3b82f6, #2563eb)' : 'linear-gradient(135deg, #2dd4bf, #0d9488)',
                boxShadow: mode === 'light' ? '0 4px 14px rgba(59, 130, 246, 0.4)' : '0 4px 14px rgba(45, 212, 191, 0.4)'
              }}
            >
              + Create New Route
            </Button>
          </Stack>
        </Stack>
      </GlassCard>

      <GlassCard sx={{ mt: 4, p: { xs: 2, md: 3 } }}>
        <TableContainer component={Box} sx={{ bgcolor: 'transparent', borderRadius: 4, overflow: 'hidden' }}>
          <Table>
            <TableHead sx={{ bgcolor: mode === 'light' ? 'rgba(0,0,0,0.02)' : 'rgba(255,255,255,0.02)' }}>
              <TableRow>
                <TableCell sx={{ fontWeight: 800 }}>Route Name</TableCell>
                <TableCell sx={{ fontWeight: 800 }}>Date</TableCell>
                <TableCell align="right" sx={{ fontWeight: 800 }}>Price (USD)</TableCell>
                <TableCell align="right" sx={{ fontWeight: 800 }}>Seats</TableCell>
                <TableCell align="center" sx={{ fontWeight: 800 }}>Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {events.map((event) => (
                <TableRow key={event._id}>
                  <TableCell component="th" scope="row">{event.name}</TableCell>
                  <TableCell>{new Date(event.date).toLocaleString()}</TableCell>
                  <TableCell align="right">${event.price}</TableCell>
                  <TableCell align="right">{event.seats}</TableCell>
                  <TableCell align="center">
                    <Stack direction="row" spacing={1} justifyContent="center">
                      <IconButton size="small" onClick={() => handleEdit(event)} aria-label="edit">
                        <EditIcon />
                      </IconButton>
                      <IconButton size="small" onClick={() => handleDelete(event._id)} aria-label="delete">
                        <DeleteIcon />
                      </IconButton>
                      <IconButton size="small" onClick={() => handleSimulateDrive(event)} aria-label="simulate drive">
                        <DirectionsBusIcon />
                      </IconButton>
                    </Stack>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      </GlassCard>

      {isModalOpen && (
        <EventForm event={editingEvent} onSave={handleSave} onClose={() => setIsModalOpen(false)} />
      )}
    </Box>
  );
};
export default AdminDashboard;

import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import GlassCard from '../components/GlassCard';
import {
  Box,
  TextField,
  Button,
  Typography,
  Stack,
  InputAdornment,
  IconButton,
  Alert,
} from '@mui/material';
import PersonOutlineIcon from '@mui/icons-material/PersonOutline';
import LockOutlinedIcon from '@mui/icons-material/LockOutlined';
import api from '../utils/api';
import { useColorMode } from '../contexts/ThemeProvider';


const AdminLoginPage = () => {
  const [username, setUsername] = useState<string>('');
  const [password, setPassword] = useState<string>('');
  const [error, setError] = useState<string>('');
  const navigate = useNavigate();
  const { mode } = useColorMode();

  const handleLogin = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    try {
      const res = await api.post('/admin/login', { username, password });
      localStorage.setItem('adminToken', res.data.token);
      navigate('/admin/dashboard');
    } catch (err: any) {
      setError('Invalid username or password.');
    }
  };

  return (
    <Box
      sx={{
        minHeight: 'calc(100vh - 96px)',
        display: 'grid',
        placeItems: 'center',
        px: 2,
        py: 4
      }}
    >
      <GlassCard sx={{ width: '100%', maxWidth: 440, p: { xs: 4, md: 5 } }}>
        <Typography variant="h4" fontWeight={900} gutterBottom sx={{
          background: mode === 'light' ? 'linear-gradient(45deg, #2563eb, #3b82f6)' : 'linear-gradient(45deg, #2dd4bf, #0ea5e9)',
          WebkitBackgroundClip: 'text',
          WebkitTextFillColor: 'transparent',
          letterSpacing: -1,
          textAlign: 'center',
          mb: 1
        }}>
          Admin Portal
        </Typography>
        <Typography variant="body1" color="text.secondary" sx={{ mb: 4, textAlign: 'center' }}>
          Secure access for authorized personnel.
        </Typography>

        {error && (
          <Alert severity="error" sx={{ mb: 3, borderRadius: 2 }}>
            {error}
          </Alert>
        )}

        <Box component="form" onSubmit={handleLogin} noValidate>
          <Stack spacing={3}>
            <TextField
              label="Username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              required
              fullWidth
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <PersonOutlineIcon fontSize="small" />
                  </InputAdornment>
                ),
                sx: {
                  borderRadius: 3,
                  bgcolor: mode === 'light' ? 'rgba(255,255,255,0.7)' : 'rgba(0,0,0,0.3)',
                  '&.Mui-focused': {
                    bgcolor: mode === 'light' ? '#fff' : 'rgba(0,0,0,0.5)'
                  }
                }
              }}
            />
            <TextField
              label="Password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              fullWidth
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <LockOutlinedIcon fontSize="small" />
                  </InputAdornment>
                ),
                sx: {
                  borderRadius: 3,
                  bgcolor: mode === 'light' ? 'rgba(255,255,255,0.7)' : 'rgba(0,0,0,0.3)',
                  '&.Mui-focused': {
                    bgcolor: mode === 'light' ? '#fff' : 'rgba(0,0,0,0.5)'
                  }
                }
              }}
            />
            <Button
              type="submit"
              variant="contained"
              size="large"
              sx={{
                mt: 2,
                borderRadius: 3,
                py: 1.5,
                fontWeight: 800,
                fontSize: '1.1rem',
                backgroundImage: mode === 'light' ? 'linear-gradient(135deg, #3b82f6, #2563eb)' : 'linear-gradient(135deg, #2dd4bf, #0d9488)',
                boxShadow: mode === 'light' ? '0 8px 20px rgba(59, 130, 246, 0.4)' : '0 8px 20px rgba(45, 212, 191, 0.4)',
                '&:hover': {
                  transform: 'translateY(-2px)',
                  boxShadow: mode === 'light' ? '0 12px 24px rgba(59, 130, 246, 0.5)' : '0 12px 24px rgba(45, 212, 191, 0.5)',
                }
              }}
            >
              Secure Login
            </Button>
          </Stack>
        </Box>
      </GlassCard>
    </Box>
  );
};
export default AdminLoginPage;
